#include <iostream>

int main() {
    // Right-associativity of assignment: a = (b += (c = 5))
    int a = 1, b = 1, c = 1;
    a = b += c = 5;
    std::cout << "a: " << a << ", b: " << b << ", c: " << c << "\n";

    // Precedence: && binds tighter than ||
    bool expr1 = true || true && false;
    std::cout << "expr1: " << std::boolalpha << expr1 << "\n";

    // Arithmetic -> Relational -> Equality -> Logical
    int val1 = 2 * 2 - 3; // 1
    int val2 = 4 - 2;     // 2
    bool expr2 = (val1 > 2) && (val2 > 5); // false && false -> false
    bool expr3 = (val1 > 2) || (val2 > 5); // false || false -> false
    std::cout << "expr2: " << expr2 << ", expr3: " << expr3 << "\n";

    return 0;
}

#include <iostream>

// A function demonstrating logic tracking and assertion-like checks
int computeDiscount(int age, bool isStudent) {
    int discountPercent = 0;
    // Debug trace output
    #ifdef DEBUG
    std::cout << "[DEBUG] age=" << age << ", isStudent=" << isStudent << "\n";
    #endif

    if (isStudent || age < 18) {
        discountPercent = 20;
    } else if (age >= 65) {
        discountPercent = 30;
    }
    return discountPercent;
}

int main() {
    int testAge = 70;
    bool testStudent = false;

    int discount = computeDiscount(testAge, testStudent);
    std::cout << "Discount: " << discount << "%\n";

    return 0;
}

#include <iostream>
#include <cmath>

int main() {
    double a = 0.0, b = 0.0, c = 0.0;
    std::cout << "Enter a, b, c: ";
    if (!(std::cin >> a >> b >> c)) {
        return 0;
    }

    double discriminant = b * b - 4 * a * c;
    const double EPSILON = 1e-9;

    if (discriminant > EPSILON) {
        double sqrtD = std::sqrt(discriminant);
        double r1 = (-b + sqrtD) / (2 * a);
        double r2 = (-b - sqrtD) / (2 * a);
        std::cout << "The roots are " << r1 << " and " << r2 << "\n";
    } else if (std::abs(discriminant) <= EPSILON) {
        double r = -b / (2 * a);
        std::cout << "The root is " << r << "\n";
    } else {
        std::cout << "The equation has no real roots\n";
    }

    return 0;
}
